# Regenerates fontData.generated.ts from fonts/inter-latin-wght.woff2 (Inter Variable, Fontsource 5.3.0; see fonts/INTER-LICENSE.txt).
# Inlined as a data URI because webpack here has no emitting loader (same reason as the photos).
import base64, os
d = os.path.dirname(os.path.abspath(__file__))
raw = open(f'{d}/fonts/inter-latin-wght.woff2', 'rb').read()
assert raw[:4] == b'wOF2', 'not a WOFF2 file'
open(f'{d}/fontData.generated.ts', 'w').write(
  '// Generated by gen_font.py. Do not edit. Inter Variable (SIL OFL 1.1), Latin subset, weight axis; see fonts/INTER-LICENSE.txt.\n'
  f"export const AVENUE_FONT_WOFF2 = 'data:font/woff2;base64,{base64.b64encode(raw).decode()}';\n")
print(len(raw))
